// Writes services/ai/src/prompts.js from prompts/studio/*.md and the studio counts in config/app.yaml,
// so the Worker (which cannot read files) owns the system prompts. `npm run gen:ai` after editing a
// prompt or a studio count; a unit test fails when the generated file is stale.
import { readFile, writeFile, readdir } from 'node:fs/promises';
import yaml from 'js-yaml';

const root = new URL('../', import.meta.url);

export async function generate() {
  const dir = new URL('prompts/studio/', root);
  const prompts = {};
  for (const f of (await readdir(dir)).filter(f => f.endsWith('.md')).sort()) prompts[f.slice(0, -3)] = (await readFile(new URL(f, dir), 'utf8')).trim();
  const S = (yaml.load(await readFile(new URL('config/app.yaml', root), 'utf8')) || {}).studio || {};
  const counts = Object.fromEntries(Object.entries(S).filter(([, v]) => typeof v === 'number'));
  return `/* GENERATED by scripts/gen-ai-prompts.mjs from prompts/studio/*.md and config/app.yaml studio. Do not edit by hand. */
export const PROMPTS = ${JSON.stringify(prompts, null, 2)};
export const COUNTS = ${JSON.stringify(counts, null, 2)};

const fill = text => text.replace(/\\{\\{(\\w+)\\}\\}/g, (m, k) => (COUNTS[k] != null ? String(COUNTS[k]) : m));

/* Shared rules + the agent's role (+ the Hinglish rule when input.lang is "hi"). The client never sends instructions. */
export function composeSystem(agent, input) {
  const parts = [PROMPTS.common, PROMPTS[agent]];
  if (input && input.lang === 'hi') parts.push(PROMPTS.hinglish);
  return fill(parts.filter(Boolean).join('\\n\\n'));
}
`;
}

if (process.argv[1] && process.argv[1].endsWith('gen-ai-prompts.mjs')) {
  await writeFile(new URL('services/ai/src/prompts.js', root), await generate());
  console.log('wrote services/ai/src/prompts.js');
}
